namespace ghidra.app.plugin.core.label;






using docking.action;
using docking.action;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.util;

class SetOperandLabelAction : ListingContextAction {
	private LabelMgrPlugin plugin;
	private static readonly string[] POPUP_PATH = new string[] { "Set Associated Label..." };
	private static readonly KeyStroke KEYBINDING =
		KeyStroke.getKeyStroke(KeyEvent.VK_L, InputEvent.CTRL_DOWN_MASK | InputEvent.ALT_DOWN_MASK);

	SetOperandLabelAction(LabelMgrPlugin plugin) : base("Set Operand Label", plugin.getName())
    {

		setPopupMenuData(new MenuData(POPUP_PATH, null, "Label"));
		setKeyBindingData(new KeyBindingData(KEYBINDING));

		this.plugin = plugin;
		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ListingActionContext context) {
		if (!(context.getLocation() is OperandFieldLocation)) {
			return false;
		}
		return !plugin.isOnExternalReference(context) && !plugin.isOnVariableReference(context) &&
			plugin.isOnSymbol(context);
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {
		plugin.setOperandLabelCallback(context);
	}
}
